import {cellPairs,fuelChoices,fuelHalfTasks,cellCorrect,fuelCorrect,fuelHalfCorrect} from './cell-models.js?v=20261023-physicscomplete01';
import {showCells} from './cell-scenes.js?v=20261023-physicscomplete01';
const field=(id,label,type='number')=>`<label class="field-label" for="cell-${id}">${label}</label><input class="lab-input" id="cell-${id}" type="${type}" ${type==='number'?'step="any"':'autocomplete="off" spellcheck="false"'}>`;
const select=(id,label,opts)=>`<label class="field-label" for="cell-${id}">${label}</label><select class="lab-select" id="cell-${id}"><option value="">Choose…</option>${opts.map(([v,s])=>`<option value="${v}">${s}</option>`).join('')}</select>`;
export function mountCellWidget(l,p,root,{save,done,feedback}){const kind=l.widget.slice(6),tasks=kind==='voltage'?cellPairs:kind==='fuel'?fuelChoices:fuelHalfTasks,correct=kind==='voltage'?cellCorrect:kind==='fuel'?fuelCorrect:fuelHalfCorrect,w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task%tasks.length,t=tasks[i],a=w.answers[t.id]??={};w.answers[t.id]=a;const $=s=>root.querySelector(s);let body='',keys=[];
if(kind==='voltage'){body=`<p><b>${i+1} / 3 · ${t.left} / ${t.right}</b></p><p>Same electrolyte and conditions: Mg/Cu gives1.6 V; Zn/Cu gives0.8 V. In both, electrons leave the more reactive Mg or Zn toward copper. Predict this pair’s voltage magnitude, direction through the wire and total for ${t.count} identical aligned cells in series.</p>`+field('voltage','Single-cell voltage / V')+select('donor','Electrons leave the…',[['left','Left electrode'],['right','Right electrode']])+field('total','Series battery voltage / V');keys=['voltage','donor','total'];}
else if(kind==='fuel'){body=`<p><b>${i+1} / 3 · ${t.title}</b></p><p>${t.prompt}</p>`+select('technology','Best supported decision',[['fuel','Hydrogen fuel cell'],['battery','Rechargeable battery'],['more','More evidence before the claim']])+select('evidence','Reason supported by the scenario',[['lifecycle','Lifecycle evidence is missing'],['turnaround','Hydrogen refuelling fits stops'],['charging','Charging fits available idle time'],['always','The chosen system is always best']]);keys=['technology','evidence'];}
else{body=`<p><b>${i+1} / 3 · ${t.title}</b></p><p>${t.prompt}</p>`+field('equation','Your half-equation','text')+'<p class="micro-note">Use ->, H+, OH- and e-. State symbols optional.</p>';keys=['equation'];}
root.innerHTML=body+'<button class="secondary" id="checkCell">Check reasoning</button><button class="secondary" id="nextCell">Next case →</button><p id="cellProgress">'+w.passed.length+' / 3 correct</p>';
const draw=()=>showCells(kind,t,w.passed.includes(t.id)&&correct(t,a));for(const k of keys){const el=$('#cell-'+k);el.value=a[k]??'';el[el.tagName==='INPUT'?'oninput':'onchange']=e=>{a[k]=e.target.value;save();draw();};}draw();
$('#checkCell').onclick=()=>{if(!correct(t,a)){feedback(kind==='voltage'?'Use the magnitude for this pair and the stated electron direction; reversing electrode positions reverses direction, not voltage magnitude. Add aligned cell voltages in series.':kind==='fuel'?'Match both the decision and its evidence to this scenario. Consider supply, turnaround and the limits of lifecycle claims.':'Balance H and O atoms, then charge. Hydrogen oxidation releases electrons; oxygen reduction takes them in. Use only the ions for the stated electrolyte.',true);return;}if(!w.passed.includes(t.id))w.passed.push(t.id);save();draw();$('#cellProgress').textContent=w.passed.length+' / 3 correct';feedback(kind==='equations'?'Balanced: species, direction, atom counts and charge agree.':'Correct: your prediction and reasoning match the supplied conditions.');if(w.passed.length===3){p.widgetDone=true;save();done();}};
$('#nextCell').onclick=()=>{w.task=(i+1)%3;save();feedback('');mountCellWidget(l,p,root,{save,done,feedback});};}
